//! 🧪️ Shared source traversal and cancellation laws exercise the parent-declared child boundary.
use super::*;
use semio_framework_io_ports::{VectorSceneCursor,VectorSceneGrant,VectorSceneEvent};
fn grant()->VectorSceneGrant {VectorSceneGrant{maximum_source_items:512,maximum_depth:32,maximum_copy_bytes:1024,maximum_capacity_bytes:1024,maximum_release_bytes:1024}}
fn tag(event:&VectorSceneEvent<'_>)->&'static str {match event {VectorSceneEvent::Canvas{..}=>"canvas",VectorSceneEvent::Style(_)=>"style",VectorSceneEvent::BeginLayer{..}=>"beginLayer",VectorSceneEvent::BeginGroup{..}=>"beginGroup",VectorSceneEvent::EndGroup=>"endGroup",VectorSceneEvent::BeginPath{..}=>"beginPath",VectorSceneEvent::Segment(_)=>"segment",VectorSceneEvent::EndPath=>"endPath",VectorSceneEvent::Text{..}=>"text",VectorSceneEvent::Image{..}=>"image",VectorSceneEvent::EndLayer=>"endLayer",VectorSceneEvent::Done=>"done"}}
#[test]
fn portable_borrowed_scene_order_and_funded_cancellation() {
    let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🔌️ports/🧵️lower/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
    for case in corpus["cases"].as_array().unwrap(){let content=semio_framework_value::DslValue::from(&case["content"]);let original=content.clone();let expected:Vec<&str>=case["events"].as_array().unwrap().iter().map(|value|value.as_str().unwrap()).collect();let cuts=corpus["cuts"].as_array().unwrap().iter().map(|value|Some(value.as_u64().unwrap()as usize)).chain(std::iter::once(None));for cut in cuts{let mut cursor=VectorSceneCursor::new();let mut events=Vec::new();for turn in 0..100{if cut.is_some_and(|cut|turn>=cut){break}let step=cursor.advance(&content,grant(),Some("stdio.semio.drawing")).unwrap();assert!(step.receipt.source_items<=512);assert!(step.receipt.retained_capacity_bytes<=1024);events.push(tag(&step.event));if let VectorSceneEvent::Image{bytes,..}=step.event{let expected=case["imageBytes"].as_array().unwrap();assert_eq!(bytes.len(),expected.len());for(index,value)in expected.iter().enumerate(){assert_eq!(bytes.get(index).unwrap(),Some(value.as_u64().unwrap()as u8))}}if matches!(step.event,VectorSceneEvent::Done){break}}if cut.is_none(){assert_eq!(events,expected)}let bytes=cursor.next_release_bytes();if bytes>0{assert!(!cursor.close_one(bytes-1));assert_eq!(cursor.next_release_bytes(),bytes);assert!(cursor.close_one(bytes));assert_eq!(cursor.last_receipt().released_bytes,bytes)}assert!(cursor.terminal_is_empty());assert_eq!(content,original)}}
}
#[test]
fn refused_scene_work_and_growth_leave_source_and_cursor_retryable(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🔌️ports/🧵️lower/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let content=semio_framework_value::DslValue::from(&corpus["cases"][0]["content"]);let mut cursor=VectorSceneCursor::new();assert!(cursor.advance(&content,VectorSceneGrant{maximum_source_items:0,..grant()},None).is_err());assert_eq!(cursor.last_receipt().source_items,0);assert!(matches!(cursor.advance(&content,grant(),None).unwrap().event,VectorSceneEvent::Canvas{..}));cursor.advance(&content,grant(),None).unwrap();cursor.advance(&content,grant(),None).unwrap();assert!(cursor.advance(&content,VectorSceneGrant{maximum_capacity_bytes:0,..grant()},None).is_err());assert_eq!(cursor.next_release_bytes(),0);assert!(matches!(cursor.advance(&content,grant(),None).unwrap().event,VectorSceneEvent::BeginGroup{..}));assert!(cursor.close_one(cursor.next_release_bytes()));}

#[test]
fn malformed_borrowed_scene_nodes_refuse_without_materializing_scene(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🔌️ports/🧵️lower/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for case in corpus["invalid"].as_array().unwrap(){let content=semio_framework_value::DslValue::from(&case["content"]);let mut cursor=VectorSceneCursor::new();let mut refused=false;for _ in 0..100{match cursor.advance(&content,grant(),None){Err(_)=>{refused=true;break},Ok(step)=>{if matches!(step.event,VectorSceneEvent::Done){break}}}}assert!(refused,"{}",case["name"]);let bytes=cursor.next_release_bytes();if bytes>0{assert!(cursor.close_one(bytes));}assert!(cursor.terminal_is_empty());}}

#[test]
fn replacing_numeric_ancestry_requires_copy_capacity_and_old_release_authority(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🔌️ports/🧵️lower/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let content=semio_framework_value::DslValue::from(&corpus["cases"][2]["content"]);let mut cursor=VectorSceneCursor::new();for _ in 0..3{cursor.advance(&content,grant(),None).unwrap();}let previous=cursor.next_release_bytes();assert!(previous>0);assert!(cursor.advance(&content,VectorSceneGrant{maximum_release_bytes:0,..grant()},None).is_err());assert_eq!(cursor.next_release_bytes(),previous);assert!(cursor.advance(&content,VectorSceneGrant{maximum_copy_bytes:0,..grant()},None).is_err());let step=cursor.advance(&content,grant(),None).unwrap();assert_eq!(step.receipt.released_bytes,previous);assert_eq!(step.receipt.copied_bytes,previous);assert!(cursor.close_one(cursor.next_release_bytes()));}
